head.script:
// 창 내용은 iframe 으로 여는 다른 WebSquare 화면. Jira 원본은 다른 서브도메인의 전체 주소(http://ww2.test.com:8080/...) + setDomain 인데
// 테스트 서버에는 그 주소가 없어 같은 서버의 전체 주소를 씀(전체 주소여야 iframe 안 mousedown 이 postMessage 로 바깥에 전달됨)
scwin.SRC = location.origin + "/websquare/websquare.html?w2xPath=/sample/common_link/windowContainer_winc_crossdomain_WPF-1319_(WSQ-2369)_winc1.xml";
scwin.onpageload = function () {
	wc.createWindow("title11", null, scwin.SRC, "test1", "11", "", "");
	wc.createWindow("title21", null, scwin.SRC, "test2", "21", "", "");
};
